using System.Net.Sockets;using System.Text;using System.Text.Json;using CloudPad.Protocol;
if(args.Length<2){Console.WriteLine("Usage: CloudPad.TestClient <IP> <PIN> [port]");return;}var host=args[0];var pin=args[1];var port=args.Length>2?int.Parse(args[2]):26760;
using var tcp=new TcpClient();await tcp.ConnectAsync(host,port);using var stream=tcp.GetStream();var hello=JsonSerializer.Serialize(new{type="HELLO",protocolVersion=1,deviceName="TestClient",pin});await stream.WriteAsync(Encoding.UTF8.GetBytes(hello+"\n"));using var reader=new StreamReader(stream,Encoding.UTF8,false,1024,true);var response=JsonDocument.Parse((await reader.ReadLineAsync())!);if(response.RootElement.GetProperty("type").GetString()!="PAIR_ACCEPTED"){Console.WriteLine(response.RootElement);return;}var id=response.RootElement.GetProperty("sessionId").GetUInt32();var token=Convert.FromBase64String(response.RootElement.GetProperty("sessionToken").GetString()!);using var udp=new UdpClient();uint seq=1;
async Task Send(ControllerState s,int ms){var until=Environment.TickCount64+ms;while(Environment.TickCount64<until){var p=new InputPacket(id,seq++,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),s,token).Serialize();await udp.SendAsync(p,p.Length,host,port);await Task.Delay(16);}}
Console.WriteLine("Sending A, left stick, RT, then neutral...");await Send(new(0,0,0,0,0,0,GamepadButtons.A),500);await Send(new(.7f,-.8f,0,0,0,0,0),700);await Send(new(0,0,0,0,0,.75f,0),500);await Send(default,200);Console.WriteLine("Done.");
